# Values are saved OUTSIDE this (public) repo, in ~/.idan-provision.env.
# Re-running the wizard offers saved values as defaults — safe to Ctrl-C.

ENV_FILE="${IDAN_PROVISION_ENV:-$HOME/.idan-provision.env}"

# code — print a copy-paste command block, indented, without clearing.
code() { printf '%s' "$DIM"; sed 's/^/      /'; printf '%s\n' "$RESET"; }

TOTAL_STAGES=11

