# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Base box setup — users, swap, packages, SSH hardening"
say "Run this as root on the box (paste the whole block):"
code <<'EOF'
apt-get update && apt-get -y upgrade
apt-get -y install git curl jq ffmpeg build-essential python3-venv
# Node 20 (Baileys bridge needs Node 18+)
curl -fsSL https://deb.nodesource.com/setup_20.x | bash - && apt-get -y install nodejs
# 2 GB swap — audit amendment 7 (4 GB RAM fits both instances only with headroom)
fallocate -l 2G /swapfile && chmod 600 /swapfile && mkswap /swapfile && swapon /swapfile
echo '/swapfile none swap sw 0 0' >> /etc/fstab
# one OS user per instance — data-level isolation
adduser --disabled-password --gecos "" nadav
adduser --disabled-password --gecos "" idan
loginctl enable-linger nadav && loginctl enable-linger idan
mkdir -p /home/nadav/.ssh /home/idan/.ssh
cp /root/.ssh/authorized_keys /home/nadav/.ssh/ && cp /root/.ssh/authorized_keys /home/idan/.ssh/
chown -R nadav:nadav /home/nadav/.ssh && chown -R idan:idan /home/idan/.ssh
chmod 700 /home/nadav/.ssh /home/idan/.ssh
# SSH hardening: keys only
sed -i 's/^#\?PasswordAuthentication.*/PasswordAuthentication no/' /etc/ssh/sshd_config
systemctl restart ssh
EOF
note "linger lets each user's systemd *user* services run without a login session."
pause "Block ran clean?"

