say "On the box, as root, install the wrapper /opt/idan/bin/ivrit-stt.sh:"
code <<'EOF'
mkdir -p /opt/idan/bin && cat > /opt/idan/bin/ivrit-stt.sh <<'WRAP'
#!/usr/bin/env bash
# ivrit-stt.sh <input_audio> <output_txt> <language>
# POSTs audio to the ivrit-ai RunPod serverless endpoint; writes transcript.
# VERIFY the payload shape against github.com/ivrit-ai/runpod-serverless README
# before first use — this is the documented shape as of 2026-08.
set -euo pipefail
in="$1"; out="$2"; lang="${3:-he}"
b64=$(base64 -w0 "$in")
resp=$(curl -sf -X POST \
  "https://api.runpod.ai/v2/${RUNPOD_ENDPOINT_ID}/runsync" \
  -H "Authorization: Bearer ${RUNPOD_API_KEY}" \
  -H "Content-Type: application/json" \
  -d "{\"input\":{\"type\":\"blob\",\"data\":\"${b64}\",\"language\":\"${lang}\"}}")
text=$(printf '%s' "$resp" | jq -r '[.output[]?.text // empty] | join(" ")')
[ -n "$text" ] || { echo "empty transcript: $resp" >&2; exit 1; }
printf '%s' "$text" > "$out"
WRAP
chmod 755 /opt/idan/bin/ivrit-stt.sh
EOF
say "Then in instance #2's config.yaml (NOT the old HERMES_LOCAL_STT_COMMAND):"
code <<'EOF'
stt:
  enabled: true
  provider: ivrit-runpod
  providers:
