      type: command
      command: "/opt/idan/bin/ivrit-stt.sh {input_path} {output_path} {language}"
      language: "he"
      format: txt
      timeout: 120
      env_passthrough: [RUNPOD_API_KEY, RUNPOD_ENDPOINT_ID]
EOF
